import { useState } from "react";

function useInput(banDau = "") {
  const [giaTri, setGiaTri] = useState(banDau);
  const onChange = (e) => setGiaTri(e.target.value);
  return { giaTri, onChange };
}

function Form() {
  const ten = useInput("");
  return (
    <div>
      <input {...ten} />
      <p>Chao {ten.giaTri}</p>
    </div>
  );
}

export default Form;
